"""Program induction, speculative mechanism generation, experimental selection.

Constructive symbolic subsystem: use a small Boolean DSL to invent competing
mechanisms from sparse observations; forecast interventions; ask a question
that makes rival hypotheses disagree; revise on the observed outcome.

This subsystem learns *by constraint-based program synthesis*, not through
neural gradient descent. Neural learned predictions live in discovery.py.
"""
from __future__ import annotations
from dataclasses import dataclass
from functools import lru_cache
import math
from .discovery import INPUTS

MASK_ALL=255

@dataclass(frozen=True)
class Program:
    mask:int
    expression:str
    complexity:int


class ProgramLibrary:
    """Induce compact rules over 3 binary controls by composing operators."""
    def __init__(self,max_complexity:int=17):
        self.programs=self._build(max_complexity)

    @staticmethod
    def truth_to_mask(truth:tuple[int,...])->int:
        if len(truth)!=8 or any(v not in (0,1) for v in truth):
            raise ValueError('Expected eight binary observations')
        return sum(int(v)<<i for i,v in enumerate(truth))

    @staticmethod
    def mask_to_truth(mask:int)->tuple[int,...]:
        if not 0<=mask<=255:raise ValueError('mask range is 0..255')
        return tuple((mask>>i)&1 for i in range(8))

    @staticmethod
    def _build(max_complexity:int)->dict[int,Program]:
        best:dict[int,Program]={}
        cost_buckets:dict[int,list[Program]]={}

        def record(mask:int,expression:str,cost:int):
            if mask in best:return
            p=Program(mask,expression,cost)
            best[mask]=p
            cost_buckets.setdefault(cost,[]).append(p)

        record(0,'FALSE',1)
        record(255,'TRUE',1)
        for k,name in enumerate('ABC'):
            mask=sum(((x[k]&1)<<i) for i,x in enumerate(INPUTS))
            record(mask,name,1)

        for cost in range(2,max_complexity+1):
            for a in list(cost_buckets.get(cost-1,[])):
                record(a.mask ^ MASK_ALL,f'NOT({a.expression})',cost)
            for lc in range(1,cost-1):
                rc=cost-1-lc
                left=cost_buckets.get(lc,[])
                right=cost_buckets.get(rc,[])
                for a in left:
                    for b in right:
                        if a.mask > b.mask:continue
                        record(a.mask & b.mask,f'({a.expression} AND {b.expression})',cost)
                        record(a.mask | b.mask,f'({a.expression} OR {b.expression})',cost)
                        record(a.mask ^ b.mask,f'({a.expression} XOR {b.expression})',cost)
            if len(best)==256:break
        return best


class HypothesisExplorer:
    """Abducts possibilities, runs thought experiments, updates from outcomes."""
    def __init__(self,library:ProgramLibrary,observed:dict[int,int]|None=None):
        self.library=library
        self.observed={}
        for k,v in (observed or {}).items(): self.observe(k,v)

    def observe(self,action:int,outcome:int):
        if action not in range(8) or outcome not in (0,1):
            raise ValueError('Action 0..7, outcome 0..1 required')
        if action in self.observed and self.observed[action]!=outcome:
            raise ValueError('Contradictory outcome; preserve observations and inspect provenance')
        self.observed[action]=outcome

    def candidates(self)->list[Program]:
        return [p for p in self.library.programs.values() if all(((p.mask>>i)&1)==v for i,v in self.observed.items())]

    def posterior(self)->list[tuple[float,Program]]:
        candidates=self.candidates()
        if not candidates:raise ValueError('No hypothesis fits these observations')
        # Simplicity prior: a simple explanation is initially preferred but
        # any consistent expression remains possible.
        weights=[math.exp(-.24*p.complexity) for p in candidates]
        denom=sum(weights)
        return sorted([(w/denom,p) for w,p in zip(weights,candidates)],key=lambda x:(-x[0],x[1].complexity))

    def predict(self,action:int)->float:
        if action not in range(8):raise ValueError('action out of range')
        if action in self.observed:return float(self.observed[action])
        return sum(prob*((p.mask>>action)&1) for prob,p in self.posterior())

    def propose_experiment(self)->dict:
        missing=[i for i in range(8) if i not in self.observed]
        if not missing:return {'action':None,'type':'KNOWLEDGE_COMPLETE','remaining_hypotheses':len(self.candidates())}
        alternatives=[]
        for i in missing:
            p=self.predict(i)
            entropy=0 if p in (0.0,1.0) else -(p*math.log2(p)+(1-p)*math.log2(1-p))
            alternatives.append((entropy,i,p))
        entropy,q,p=max(alternatives,key=lambda e:(e[0],-e[1]))
        return {'type':'DISCRIMINATE_MECHANISMS','action':q,'input':list(INPUTS[q]),
                'predicted_state_1_probability':round(p,5),'disagreement_entropy':round(entropy,5),
                'remaining_hypotheses':len(self.candidates()),'alternatives':len(missing)}

    def propose_goal(self,goal:int)->dict:
        if goal not in (0,1):raise ValueError('Goal must be 0 or 1')
        missing=[i for i in range(8) if i not in self.observed]
        if not missing:return {'action':None,'status':'ALL_INTERVENTIONS_OBSERVED'}
        scored=[]
        for i in missing:
            p=self.predict(i)
            p_goal=p if goal==1 else 1-p
            scored.append((p_goal,i))
        p_goal,q=max(scored,key=lambda x:(x[0],-x[1]))
        best=self.posterior()[:3]
        return {'status':'GOAL_DIRECTED_HYPOTHESIS','action':q,'input':list(INPUTS[q]),
                'goal':goal,'predicted_goal_probability':round(p_goal,5),
                'hypothesized_mechanism':best[0][1].expression,
                'alternative_mechanisms':[{'rule':p.expression,'probability':round(w,4)} for w,p in best[1:]],
                'candidate_count':len(self.candidates())}

    def discover(self,world,goal:int,max_interventions:int=3)->dict:
        """Act in synthetic world, observe outcomes, revise and pursue goal."""
        if max_interventions<1:raise ValueError('Need at least one intervention')
        history=[]
        for _ in range(max_interventions):
            candidate=self.propose_goal(goal)
            q=candidate['action']
            if q is None:break
            result=world.truth[q]
            before=len(self.candidates())
            self.observe(q,result)
            after=len(self.candidates())
            history.append({'proposed_intervention':candidate,
                           'observed':result,'hypotheses_before':before,
                           'hypotheses_after':after})
            if result==goal:break
        return {'goal':goal,'success':bool(history and history[-1]['observed']==goal),
                'interventions':history,'remaining_hypotheses':len(self.candidates()),
                'observed_count':len(self.observed)}


def transfer_truth(truth:tuple[int,...],role_permutation:tuple[int,int,int])->tuple[int,...]:
    """Transfer a learned rule to new domain roles; no name matching."""
    if sorted(role_permutation)!=[0,1,2]:raise ValueError('Expected 3 distinct role indices')
    return tuple(truth[INPUTS.index(tuple(x[i] for i in role_permutation))] for x in INPUTS)
