import json,math
from pathlib import Path
import numpy as np
import torch
from src.discovery import FewShotPredictor,make_dataset,encode_observed

torch.set_num_threads(2)
out=Path('output')
models={}
for tag,fil in [('original','constructive_predictor.pt'),('novel_adapted','constructive_predictor_adapted.pt'),('balanced','candidate_equal.pt')]:
    m=FewShotPredictor(); ck=torch.load(out/fil,weights_only=True,map_location='cpu');m.load_state_dict(ck['state_dict']);m.eval();models[tag]=m

def pred(model,features):
    with torch.no_grad(): return torch.sigmoid(model(torch.from_numpy(features))).numpy()

def eval_split(rows,temperatures):
    full=np.stack([encode_observed(e.observed,e.query) for e in rows])
    holds=[]
    labels=[]
    for e in rows:
        for idx,val in e.observed.items():
            reduced={k:v for k,v in e.observed.items() if k!=idx}
            holds.append(encode_observed(reduced,idx)); labels.append(val)
    holds=np.stack(holds); labels=np.array(labels,dtype=float).reshape((-1,4))
    out_prob={tag:pred(m,full) for tag,m in models.items()}
    nll={}
    for tag,m in models.items():
        p=np.clip(pred(m,holds).reshape((-1,4)),1e-5,1-1e-5)
        nll[tag]=np.mean(-(labels*np.log(p)+(1-labels)*np.log(1-p)),axis=1)
    y=np.array([e.target for e in rows])
    report={tag:round(float(np.mean((p>=.5)==y)),4) for tag,p in out_prob.items()}
    for tag2 in ['novel_adapted','balanced']:
        for temp in temperatures:
            weight=1/(1+np.exp(np.clip((nll['original']-nll[tag2])*temp,-20,20)))
            combined=weight*out_prob['original']+(1-weight)*out_prob[tag2]
            score=round(float(np.mean((combined>=.5)==y)),4)
            report[f'router_{tag2}_temp{temp}']=score
    return report

res={}
for split,seed in [('new_domains',999222),('novel_mechanisms',999111)]:
    cases=make_dataset(1500,seed,split=split)
    res[split]=eval_split(cases,[.5,1,2,4,8])
print(json.dumps(res,indent=2))
(out/'expert_router_experiment.json').write_text(json.dumps(res,indent=2))
